using System.Net;using System.Text.Json;using Microsoft.AspNetCore.Hosting;using Microsoft.AspNetCore.Mvc.Testing;
namespace SanSo.Api.Tests;
public class ProductionAuthorizationV2Tests
{
 [Fact]public async Task ProductionApiRejectsTenantHeaderWithoutBearerWithSafeBody(){await using var factory=new WebApplicationFactory<Program>().WithWebHostBuilder(x=>x.UseEnvironment("Production"));using var client=factory.CreateClient();using var request=new HttpRequestMessage(HttpMethod.Get,"/api/dashboard");request.Headers.Add("X-Tenant-Id","tenant-an-nhien");var response=await client.SendAsync(request);Assert.Equal(HttpStatusCode.Unauthorized,response.StatusCode);using var body=JsonDocument.Parse(await response.Content.ReadAsStringAsync());Assert.Equal(401,body.RootElement.GetProperty("status").GetInt32());Assert.True(body.RootElement.TryGetProperty("correlationId",out _));Assert.DoesNotContain("stack",body.RootElement.ToString(),StringComparison.OrdinalIgnoreCase);}
 [Fact]public async Task DevelopmentDemoModeAllowsCredentiallessFirstReconciliation(){await using var factory=new WebApplicationFactory<Program>().WithWebHostBuilder(x=>x.UseEnvironment("Development"));using var client=factory.CreateClient();using var request=new HttpRequestMessage(HttpMethod.Get,"/api/reconciliations/current");request.Headers.Add("X-Tenant-Id","tenant-an-nhien");var response=await client.SendAsync(request);Assert.Equal(HttpStatusCode.OK,response.StatusCode);}
}
